export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"distracting-a-way-to-remember-these-skills-is-the-phrase-wise-mind-accepts-with-384aad2fa972\",\"title\":\"Distracting A way to remember these skills is the phrase \u201cWise Mind ACCEPTS.\u201d With Activities: \\u0003\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9797],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/05-dbt-distress-tolerance-distress-tolerance-handout-7-distracting-a-way-to-remember-these-s-a638353902.json\",\"sha256\":\"a638353902ec489b79779200d92a0d4bdc0a50720485be1085a653d8693711a5\",\"domain\":\"dbt\",\"bytes\":7762},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/distress-tolerance-handout-7-distracting-a-way-to-remember-these-skills-is-the-phrase-wise-m-0f5185b622.json\",\"sha256\":\"0f5185b62201d4fc08ec893e7b340778bd6255d87b87ac10cafde1d462caf37a\",\"domain\":\"dbt\",\"bytes\":7602}]},\"data\":{\"pages\":[{\"pdf_page\":357,\"book_page\":\"333\",\"text\":\"333\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nDistress Tolerance Handout 7   (Distress Tolerance Worksheets 5\u20135b)\\nDistracting\\nA way to remember these skills is the phrase \u201cWise Mind ACCEPTS.\u201d\\nWith Activities:\\n\\u0003\\n\u0089 Focus attention on a task you need to get\\ndone.\\n\\u0003\\n\u0089 Rent movies; watch TV.\\n\\u0003\\n\u0089 Clean a room in your house.\\n\\u0003\\n\u0089 Find an event to go to.\\n\\u0003\\n\u0089 Play computer games.\\n\\u0003\\n\u0089 Go walking. Exercise.\\n\\u0003\\n\u0089 Surf the Internet. Write e-mails.\\n\\u0003\\n\u0089 Play sports.\\n\\u0003\\n\u0089 Go out for a meal or eat a favorite food.\\n\\u0003\\n\u0089 Call or go out with a friend.\\n\\u0003\\n\u0089 Listen to your iPod; download music.\\n\\u0003\\n\u0089 Build something.\\n\\u0003\\n\u0089 Spend time with your children.\\n\\u0003\\n\u0089 Play cards.\\n\\u0003\\n\u0089 Read magazines, books, comics.\\n\\u0003\\n\u0089 Do crossword puzzles or Sudoku.\\n\\u0003\\n\u0089 Other:\\nWith Contributing:\\n\\u0003\\n\u0089 Find volunteer work to do.\\n\\u0003\\n\u0089 Help a friend or family member.\\n\\u0003\\n\u0089 Surprise someone with something nice (a\\ncard, a favor, a hug).\\n\\u0003\\n\u0089 Give away things you don\u2019t need.\\n\\u0003\\n\u0089 Call or send an instant message encouraging\\nsomeone or just saying hi.\\n\\u0003\\n\u0089 Make something nice for someone else.\\n\\u0003\\n\u0089 Do something thoughtful.\\n\\u0003\\n\u0089 Other:\\nWith Comparisons:\\n\\u0003\\n\u0089 Compare how you are feeling now to a time\\nwhen you felt different.\\n\\u0003\\n\u0089 Think about people coping the same as you or\\nless well than you.\\n\\u0003\\n\u0089 Compare yourself to those less fortunate.\\n\\u0003\\n\u0089 Watch reality shows about others\u2019 troubles;\\nread about disasters, others\u2019 suffering.\\n\\u0003\\n\u0089 Other:\\nWith different Emotions:\\n\\u0003\\n\u0089 Read emotional books or stories, old letters.\\n\\u0003\\n\u0089 Watch emotional TV shows; go to emotional\\nmovies.\\n\\u0003\\n\u0089 Listen to emotional music.\\n(Be sure the event creates different emotions.)\\nIdeas: Scary movies, joke books, comedies,\\nfunny records, religious music, soothing music\\nor music that fires you up, going to a store and\\nreading funny greeting cards.\\n\\u0003\\n\u0089 Other:\\nWith Pushing away:\\n\\u0003\\n\u0089 Push the situation away by leaving it for a\\nwhile.\\n\\u0003\\n\u0089 Leave the situation mentally.\\n\\u0003\\n\u0089 Build an imaginary wall between yourself and\\nthe situation.\\n\\u0003\\n\u0089 Block thoughts and images from your mind.\\n\\u0003\\n\u0089 Notice ruminating: Yell \u201cNo!\u201d\\n\\u0003\\n\u0089 Refuse to think about the painful situations.\\n\\u0003\\n\u0089 Put the pain on a shelf. Box it up and put it\\naway for a while.\\n\\u0003\\n\u0089 Deny the problem for the moment.\\n\\u0003\\n\u0089 Other:\\nWith other Thoughts:\\n\\u0003\\n\u0089 Count to 10; count colors in a painting or\\nposter or out the window; count anything.\\n\\u0003\\n\u0089 Repeat words to a song in your mind.\\n\\u0003\\n\u0089 Work puzzles.\\n\\u0003\\n\u0089 Watch TV or read.\\n\\u0003\\n\u0089 Other:\\nWith other Sensations:\\n\\u0003\\n\u0089 Squeeze a rubber ball very hard.\\n\\u0003\\n\u0089 Listen to very loud music.\\n\\u0003\\n\u0089 Hold ice in your hand or mouth.\\n\\u0003\\n\u0089 Go out in the rain or snow.\\n\\u0003\\n\u0089 Take a hot or cold shower.\\n\\u0003\\n\u0089 Other:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Distress Tolerance Handout 7   (Distress Tolerance Worksheets 5\u20135b)\",\"source_pdf_pages\":[357],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/distress_tolerance/handouts/distress_tolerance_handout_7_distracting_a_way_to_remember_these_skills_is_the_phrase_wise_mind_acc.json\",\"item_number\":\"7\",\"full_text\":\"Distress Tolerance Handout 7   (Distress Tolerance Worksheets 5\u20135b)\\nDistracting\\nA way to remember these skills is the phrase \u201cWise Mind ACCEPTS.\u201d\\nWith Activities:\\n\\u0003\\n\u0089 Focus attention on a task you need to get\\ndone.\\n\\u0003\\n\u0089 Rent movies; watch TV.\\n\\u0003\\n\u0089 Clean a room in your house.\\n\\u0003\\n\u0089 Find an event to go to.\\n\\u0003\\n\u0089 Play computer games.\\n\\u0003\\n\u0089 Go walking. Exercise.\\n\\u0003\\n\u0089 Surf the Internet. Write e-mails.\\n\\u0003\\n\u0089 Play sports.\\n\\u0003\\n\u0089 Go out for a meal or eat a favorite food.\\n\\u0003\\n\u0089 Call or go out with a friend.\\n\\u0003\\n\u0089 Listen to your iPod; download music.\\n\\u0003\\n\u0089 Build something.\\n\\u0003\\n\u0089 Spend time with your children.\\n\\u0003\\n\u0089 Play cards.\\n\\u0003\\n\u0089 Read magazines, books, comics.\\n\\u0003\\n\u0089 Do crossword puzzles or Sudoku.\\n\\u0003\\n\u0089 Other:\\nWith Contributing:\\n\\u0003\\n\u0089 Find volunteer work to do.\\n\\u0003\\n\u0089 Help a friend or family member.\\n\\u0003\\n\u0089 Surprise someone with something nice (a\\ncard, a favor, a hug).\\n\\u0003\\n\u0089 Give away things you don\u2019t need.\\n\\u0003\\n\u0089 Call or send an instant message encouraging\\nsomeone or just saying hi.\\n\\u0003\\n\u0089 Make something nice for someone else.\\n\\u0003\\n\u0089 Do something thoughtful.\\n\\u0003\\n\u0089 Other:\\nWith Comparisons:\\n\\u0003\\n\u0089 Compare how you are feeling now to a time\\nwhen you felt different.\\n\\u0003\\n\u0089 Think about people coping the same as you or\\nless well than you.\\n\\u0003\\n\u0089 Compare yourself to those less fortunate.\\n\\u0003\\n\u0089 Watch reality shows about others\u2019 troubles;\\nread about disasters, others\u2019 suffering.\\n\\u0003\\n\u0089 Other:\\nWith different Emotions:\\n\\u0003\\n\u0089 Read emotional books or stories, old letters.\\n\\u0003\\n\u0089 Watch emotional TV shows; go to emotional\\nmovies.\\n\\u0003\\n\u0089 Listen to emotional music.\\n(Be sure the event creates different emotions.)\\nIdeas: Scary movies, joke books, comedies,\\nfunny records, religious music, soothing music\\nor music that fires you up, going to a store and\\nreading funny greeting cards.\\n\\u0003\\n\u0089 Other:\\nWith Pushing away:\\n\\u0003\\n\u0089 Push the situation away by leaving it for a\\nwhile.\\n\\u0003\\n\u0089 Leave the situation mentally.\\n\\u0003\\n\u0089 Build an imaginary wall between yourself and\\nthe situation.\\n\\u0003\\n\u0089 Block thoughts and images from your mind.\\n\\u0003\\n\u0089 Notice ruminating: Yell \u201cNo!\u201d\\n\\u0003\\n\u0089 Refuse to think about the painful situations.\\n\\u0003\\n\u0089 Put the pain on a shelf. Box it up and put it\\naway for a while.\\n\\u0003\\n\u0089 Deny the problem for the moment.\\n\\u0003\\n\u0089 Other:\\nWith other Thoughts:\\n\\u0003\\n\u0089 Count to 10; count colors in a painting or\\nposter or out the window; count anything.\\n\\u0003\\n\u0089 Repeat words to a song in your mind.\\n\\u0003\\n\u0089 Work puzzles.\\n\\u0003\\n\u0089 Watch TV or read.\\n\\u0003\\n\u0089 Other:\\nWith other Sensations:\\n\\u0003\\n\u0089 Squeeze a rubber ball very hard.\\n\\u0003\\n\u0089 Listen to very loud music.\\n\\u0003\\n\u0089 Hold ice in your hand or mouth.\\n\\u0003\\n\u0089 Go out in the rain or snow.\\n\\u0003\\n\u0089 Take a hot or cold shower.\\n\\u0003\\n\u0089 Other:\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Distress Tolerance Worksheets 5\u20135b\"],\"id\":\"distress_tolerance_handout_7\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"333\"],\"title\":\"Distracting A way to remember these skills is the phrase \u201cWise Mind ACCEPTS.\u201d With Activities: \\u0003\",\"module_category\":\"Distress Tolerance Skills\",\"shared_json_path\":\"shared/05_dbt_distress_tolerance/handouts_json/distress_tolerance_handout_7_distracting_a_way_to_remember_these_skills_i_e0a03a69.json\",\"module\":\"Distress Tolerance\",\"keywords\":[\"ACCEPTS\",\"Activities\",\"Distracting\",\"Mind\",\"Wise\",\"With\",\"phrase\",\"remember\",\"skills\",\"these\"]}}");
